/* Horizontal strategy panels stay fully opaque while they travel through the viewport.
   Visibility only culls whole panels beyond the viewport, with one CSS pixel of overscan. */
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

export function oceanProgress(u, count = 4, reducedMotion = false) {
  const end = Math.max(0, count - 1);
  const progress = clamp(Number.isFinite(u) ? u : 0, 0, end);
  if (reducedMotion || progress >= .25) return progress;

  // Hermite join: position 0 / slope 0 at the start, position .25 / slope 1 at the join.
  // All later integer chapter stops remain exact.
  const t = progress / .25;
  return .25 * t * t * (2 - t);
}

export function oceanPanelState({ index, progress, width, reducedMotion = false, count = 4 }) {
  const end = Math.max(0, count - 1);
  const p = clamp(Number.isFinite(progress) ? progress : 0, 0, end);
  if (reducedMotion) return { x: 0, visible: index === Math.round(p), opacity: 1 };

  const viewportWidth = Math.max(1, Number.isFinite(width) ? width : 1);
  const x = (index - p) * viewportWidth;
  const overscan = 1;
  const visible = x <= viewportWidth + overscan && x + viewportWidth >= -overscan;
  return { x, visible, opacity: 1 };
}
